#include <cstdio>
#include <algorithm>

using namespace std;

struct Item {
    int value;
    int weight;
};

int main() {
    for(int caseNum = 1, weight; scanf("%d", &weight), weight; caseNum++) {
        int itemCount;
        scanf("%d", &itemCount);
        Item items[1001];
        for(int i = 0; i < itemCount; i++) {
            // Optimized: Read value and weight in one go
            scanf("%d,%d", &items[i].value, &items[i].weight);
        }

        int dp[1001] = {0};
        for(int i = 0; i < itemCount; i++) {
            for(int j = weight; j >= items[i].weight; j--) {
                dp[j] = max(dp[j], dp[j - items[i].weight] + items[i].value);
            }
        }

        int maxProfit = dp[weight], bestWeight;
        for(int j = 0; j <= weight; j++) {
            if(maxProfit == dp[j]) { bestWeight = j; break; }
        }

        printf("Case %d:\n", caseNum);
        printf("%d\n%d\n", maxProfit, bestWeight);
    }
    return 0;
}

